<?php
function conversation(string $id): array {if(!isUuid($id))fail('Conversation not found.',404);$r=one("SELECT c.*,(SELECT body FROM messages WHERE conversation_id=c.id AND sender<>'system' ORDER BY id DESC LIMIT 1) AS last_body FROM conversations c WHERE c.id=?",[$id]);if(!$r)fail('Conversation not found.',404);return ['id'=>$r['id'],'name'=>$r['customer_name'],'phone'=>$r['customer_phone'],'unread'=>(int)$r['unread_staff'],'lastAt'=>$r['last_message_at'].'Z','lastBody'=>$r['last_body']??''];}
function messages(string $id): array {conversation($id);$out=[];foreach(array_reverse(rows('SELECT m.*,p.slug AS p_slug,p.name AS p_name,(SELECT base_name FROM product_images WHERE product_id=p.id ORDER BY sort,id LIMIT 1) AS p_img FROM messages m LEFT JOIN products p ON p.id=m.product_id WHERE m.conversation_id=? ORDER BY m.id DESC LIMIT 300',[$id])) as $r)$out[]=['id'=>(int)$r['id'],'conversationId'=>$id,'sender'=>$r['sender'],'body'=>$r['body'],'createdAt'=>$r['created_at'].'Z','product'=>$r['p_slug']?['slug'=>$r['p_slug'],'name'=>$r['p_name'],'thumb'=>$r['p_img']?'/uploads/products/'.$r['p_img'].'-sm.jpg':null]:null];return $out;}
function saveMessage(string $id,string $sender,array $b): array {
    conversation($id);$body=textValue($b['body']??'',2000);if(!$body)fail('Enter a message before sending.');$pid=num($b['productId']??0)?:null;if($pid&&!one('SELECT id FROM products WHERE id=?',[$pid]))$pid=null;
    $mid=tx(function()use($id,$sender,$body,$pid){$mid=insert('messages',['conversation_id'=>$id,'sender'=>$sender,'body'=>$body,'product_id'=>$pid]);sql("UPDATE conversations SET last_message_at=NOW(3),unread_staff=CASE WHEN ?='customer' THEN unread_staff+1 WHEN ?='staff' THEN 0 ELSE unread_staff END WHERE id=?",[$sender,$sender,$id]);return $mid;});foreach(messages($id) as $m)if($m['id']===$mid)return $m;return [];
}
function conversations(array $q): mixed {$out=[];foreach(rows("SELECT c.id FROM conversations c WHERE EXISTS(SELECT 1 FROM messages WHERE conversation_id=c.id AND sender<>'system') ORDER BY last_message_at DESC") as $r){$c=conversation($r['id']);if(($q['unread']??'')==='1'&&!$c['unread'])continue;$search=clean($q['q']??'',100);if($search&&!contains(($c['name']??'').' '.($c['phone']??''),$search)&&!one("SELECT id FROM messages WHERE conversation_id=? AND sender<>'system' AND body LIKE ? LIMIT 1",[$c['id'],'%'.addcslashes($search,'_%\\').'%']))continue;$out[]=$c;}return isset($q['page'])?pageResult($out,$q):array_slice($out,0,200);}
function quotes(array $q): mixed {$out=[];foreach(rows('SELECT q.*,p.name AS product_name FROM quote_requests q LEFT JOIN products p ON p.id=q.product_id ORDER BY q.created_at DESC,q.id DESC') as $r){if(!empty($q['status'])&&$r['status']!==$q['status'])continue;if(!contains(implode(' ',array_map(fn($v)=>(string)$v,[$r['customer_name'],$r['customer_phone'],$r['customer_email'],$r['requirement'],$r['product_name']])),clean($q['q']??'',100)))continue;$out[]=$r;}return isset($q['page'])?pageResult($out,$q):array_slice($out,0,200);}
